NO_OF_CHARS = 256

def removeChars(str1, str2):
    # Create a boolean array to mark characters present in str2
    mark = [False] * NO_OF_CHARS

    for ch in str2:
        mark[ord(ch)] = True

    # Build result string with characters from str1 that are not in str2
    result = []
    for ch in str1:
        if not mark[ord(ch)]:
            result.append(ch)

    return ''.join(result)

