def is_sublist(l, s):
    # An empty sublist is always considered a sublist
    if not s:
        return True

    # If s is longer than l, it can't be a sublist of l
    if len(s) > len(l):
        return False

    # Check for the sublist using a sliding window approach
    for i in range(len(l) - len(s) + 1):
        if l[i:i+len(s)] == s:
            return True
    return False

# Sample tests 
if __name__ == '__main__':
    print(is_sublist([1, 2, 3, 4, 5], [2, 3]))  # True
    print(is_sublist([1, 2, 3, 4, 5], [3, 5]))  # False
    print(is_sublist([1, 2, 3], []))            # True
    print(is_sublist([], [1]))                  # False

