def is_undulating(n):
    s = str(n)
    # An undulating number must have at least two digits
    if len(s) < 2:
        return False
    # The first two digits must be different
    if s[0] == s[1]:
        return False
    # Check each digit according to its position
    for i, digit in enumerate(s):
        if i % 2 == 0:
            if digit != s[0]:
                return False
        else:
            if digit != s[1]:
                return False
    return True

