def power(a, b):
    # When exponent is 0, the result is always 1
    if b == 0:
        return 1
    # Flag to determine if the exponent is negative
    negative_exponent = b < 0
    if negative_exponent:
        b = -b
    result = 1
    # Multiply result by a, b times
    for _ in range(b):
        result *= a
    return 1 / result if negative_exponent else result

