def divisor(n):
    if n < 1:
        raise ValueError('n must be a positive integer')
    count = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            # If i is the square root of n, count it once
            if i * i == n:
                count += 1
            else:
                count += 2
        i += 1
    return count

